"shell\"><span>Superintelligence SG Commons</span><a href=\"mailto:superintelligencesg@gmail.com\">superintelligencesg@gmail.com</a><a href=\"#top\">Back to top</a></footer>\n  <script>\n    const API='https://api.superintelligencesg.org',list=document.querySelector('[data-list]'),status=document.querySelector('[data-status]'),profile=document.querySelector('[data-profile]'),search=document.querySelector('.search'),sort=document.querySelector('.sort');let entries=[],query='',order='latest';const slug=value=>encodeURIComponent(value.trim().toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/(^-|-$)/g,''));function shown(){const needle=query.toLowerCase().trim(),filtered=entries.filter(item=>!needle||[item.name,item.founder,item.business].join(' ').toLowerCase().includes(needle));return order==='az'?[...filtered].sort((a,b)=>a.name.localeCompare(b.name)):filtered}function render(){const items=shown();list.replaceChildren();status.textContent=`${items.length} ${items.length===1?'organization':'organizations'} shown`;if(!items.length){const empty=document.createElement('p');empty.className='empty';empty.textContent=query?'No published organization matches that search.':'The directory is open. Your organization can be the first to join.';list.append(empty);return}for(const item of items){const card=document.createElement('article');card.className='org-card';const image=document.createElement('img');image.className='org-logo';image.src=item.logo_key;image.alt=`${item.name} logo`;image.loading='lazy';const content=document.createElement('div');const name=document.createElement('h2'),founder=document.createElement('p'),work=document.createElement('p');name.textContent=item.name;founder.className='founder';founder.textContent=`Founded by ${item.founder}`;work.className='work';work.textContent=item.business;content.append(name,founder,work);const link=document.createElement('a');link.className='view';link.href='#'+slug(item.name);link.textContent='View profile';link.addEventListener('click',()=>openProfile(item));card.append(image,content,link);list.append(card)}}function openProfile(item){profile.dataset.open='true';profile.replaceChildren();const mark=document.createElement('div'),image=document.createElement('img'),copy=document.createElement('div'),name=document.createElement('h2'),founder=document.createElement('p'),work=document.createElement('p'),close=document.createElement('a');mark.className='profile-mark';image.src=item.logo_key;image.alt=`${item.name} logo`;copy.className='profile-copy';name.textContent=item.name;founder.className='founder';founder.textContent=`Founded by ${item.founder}`;work.className='work';work.textContent=item.business;close.className='profile-close';close.href='#directory';close.textContent='Back to all organizations';close.addEventListener('click',()=>{profile.dataset.open='false';history.replaceState(null,'',location.pathname+'#directory')});mark.append(image);copy.append(name,founder,work,close);profile.append(mark,copy);profile.scrollIntoView({behavior:'smooth',block:'start'})}async function load(){try{const response=await fetch(`${API}/api/organizations`);if(!response.ok)throw Error();const payload=await response.json();entries=payload.organizations||[];render();const active=decodeURIComponent(location.hash.slice(1));const item=entries.find(entry=>slug(entry.name)===active);if(item)openProfile(item)}catch{status.textContent='Directory temporarily unavailable';list.replaceChildren();const empty=document.createElement('p');empty.className='empty';empty.textContent='The directory could not be reached. Please return to the Commons and try again.';list.append(empty)}}search.addEventListener('input',()=>{query=search.value;render()});sort.addEventListener('change',()=>{order=sort.value;render()});load();\n  </script>\n  <script>\n    (async()=>{try{const response=await fetch('https://api.superintelligencesg.org/api/organizations');if(!response.ok)return;const payload=await response.json(),byName=new Map((payload.organizations||[]).map(item=>[item.name,item]));const label=value=>value==='claimed'?'Claimed · contact confirmed':value==='reviewed'?'Reviewed · public facts checked':'Submitted · self-published';const decorate=()=>{document.querySelectorAll('.org-card').forEach(card=>{const name=card.querySelector('h2')?.textContent,item=byName.get(name);if(item&&!card.querySelector('.verification')){const node=document.createElement('p');node.className='verification';node.textContent=label(item.verification_status);card.querySelector('.work')?.before(node)}});const profile=document.querySelector('[data-profile][data-open=true]');if(profile&&!profile.querySelector('.verification')){const name=profile.querySelector('h2')?.textContent,item=byName.get(name);if(item){const node=document.createElement('p');node.className='verification';node.textContent=label(item.verification_status);profile.querySelector('.work')?.before(node);const claim=document.createElement('a');claim.className='profile-close';claim.href=`mailto:superintelligencesg@gmail.com?subject=Claim%20organization%20profile%3A%20${encodeURIComponent(item.name)}`;claim.textContent='Claim or correct this profile';profile.querySelector('.profile-copy')?.append(claim)}}};new MutationObserver(decorate).observe(document.querySelector('[data-list]'),{childList:true});new MutationObserver(decorate).observe(document.querySelector('[data-profile]'),{childList:true,attributes:true});decorate()}catch{}})();\n  </script>\n</body>\n</html>\n";
const ALLOWED_ORIGINS = new Set(["https://superintelligencesg.org","https://www.superintelligencesg.org","https://superintelligencesg.com","https://www.superintelligencesg.com","https://api.superintelligencesg.org"]);
function headers(origin){const h=new Headers({"Content-Type":"application/json; charset=utf-8","Cache-Control":"no-store","X-Content-Type-Options":"nosniff"});if(origin&&ALLOWED_ORIGINS.has(origin)){h.set("Access-Control-Allow-Origin",origin);h.set("Access-Control-Allow-Methods","GET, POST, OPTIONS");h.set("Access-Control-Allow-Headers","Content-Type");h.set("Vary","Origin");}return h}
function json(d,s,o){return new Response(JSON.stringify(d),{status:s,headers:headers(o)})}
function validImage(b,t){if(t==="image/png")return b.length>=8&&b[0]===137&&b[1]===80&&b[2]===78&&b[3]===71;if(t==="image/jpeg")return b.length>=3&&b[0]===255&&b[1]===216&&b[2]===255;if(t==="image/webp")return b.length>=12&&String.fromCharCode(...b.slice(0,4))==="RIFF"&&String.fromCharCode(...b.slice(8,12))==="WEBP";return false}
function toBase64(bytes){let binary="";for(let i=0;i<bytes.length;i+=32768)binary+=String.fromCharCode(...bytes.subarray(i,i+32768));return btoa(binary)}
async function rateKey(ip){const d=await crypto.subtle.digest("SHA-256",new TextEncoder().encode(ip||"unknown"));return Array.from(new Uint8Array(d),x=>x.toString(16).padStart(2,"0")).join("")}
function hasMissingVerificationColumns(error){return /no such column|no column named|has no column named/i.test(String(error?.message||error||""))}
async function organizationRows(env){try{const r=await env.DB.prepare("SELECT id,name,founder,business,logo_key,created_at,verification_status,updated_at FROM organizations ORDER BY created_at DESC LIMIT 100").all();return r.results||[]}catch(error){if(!hasMissingVerificationColumns(error))throw error;const r=await env.DB.prepare("SELECT id,name,founder,business,logo_key,created_at FROM organizations ORDER BY created_at DESC LIMIT 100").all();return (r.results||[]).map(item=>({...item,verification_status:"submitted",updated_at:item.created_at}))}}
